begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(11);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp181@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18100000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18100000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18100000-0000-0000-0000-000000000004','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18100000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18100000-0000-0000-0000-000000000005','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18100000-0000-0000-0000-000000000006','18100000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18100000-0000-0000-0000-000000000007','18100000-0000-0000-0000-000000000002','Synthetic staff');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18100000-0000-0000-0000-000000000008','18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
grant usage on schema extensions to mcp_import;
grant execute on all functions in schema extensions to mcp_import;
insert into public.staff_roles(id,organization_id,name) values ('18100000-0000-0000-0000-000000000011','18100000-0000-0000-0000-000000000002','Synthetic role');
insert into public.staffs(id,organization_id,name) values ('18100000-0000-0000-0000-000000000010','18100000-0000-0000-0000-000000000002','Other synthetic staff');
insert into public.shift_segments(id,shift_id,start_at,end_at) values ('18100000-0000-0000-0000-000000000012','18100000-0000-0000-0000-000000000008','2026-11-01 00:00+00','2026-11-01 01:00+00');
insert into public.shift_segment_staffs(segment_id,staff_id,staff_role_id) values ('18100000-0000-0000-0000-000000000012','18100000-0000-0000-0000-000000000007','18100000-0000-0000-0000-000000000011');
select ok(has_function_privilege('mcp_import','public.get_mcp_shift_update_template(uuid,uuid)','execute') and not has_function_privilege('authenticated','public.get_mcp_shift_update_template(uuid,uuid)','execute'),'template restricted to MCP');
set local role mcp_import;
select throws_ok($$select public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')$$,'42501','proposal_unavailable','default disabled');
reset role;
insert into private.mcp_shift_update_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
set local role mcp_import;
select is(public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')->'shift'->'segments'->0->'staffs'->0->>'staff_role_id','18100000-0000-0000-0000-000000000011','existing role included');
select is(public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')->'references'->'staff_roles'->0->>'name','Synthetic role','role name included');
select is(public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')->'draft_segments'->0->'staffs'->0->>'staff_role_id','18100000-0000-0000-0000-000000000011','draft keeps the current staff role');
select ok(not ((public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')->'draft_segments'->0) ? 'id'),'draft excludes read-only segment identifiers');
select ok(not ((public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')->'shift') ? 'report_statuses'),'record statuses excluded');
select throws_ok($$select public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000099','18100000-0000-0000-0000-000000000008')$$,'42501','mcp_shift_read_unavailable','other organization denied');
reset role;
update public.staffs set deleted_at=clock_timestamp() where id='18100000-0000-0000-0000-000000000007';
set local role mcp_import;
select throws_ok($$select public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')$$,'42501','proposal_unavailable','deleted staff identity not disclosed');
select throws_ok($$select public.prepare_mcp_shift_update('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008','2026-11-01 02:00+00','2026-11-01 03:00+00','[{"start_at":"2026-11-01T02:00:00Z","end_at":"2026-11-01T03:00:00Z","staffs":[{"staff_id":"18100000-0000-0000-0000-000000000010"}]}]')$$,'42501','proposal_unavailable','proposal with deleted original identity rejected');
reset role;
update public.staffs set deleted_at=null where id='18100000-0000-0000-0000-000000000007';
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18100000-0000-0000-0000-000000000004';
set local role mcp_import;
select throws_ok($$select public.get_mcp_shift_update_template('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000008')$$,'42501','mcp_shift_read_unavailable','revoked OAuth denied');
reset role;
select * from finish();
rollback;
